pub enum Msg {
    Ping,
    Hello(String),
    Heartbeat(u32),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if let Some(message) = bytes.strip_prefix("v:2|hello:") {
        return Ok(Msg::Hello(message.into()));
    }
    if let Some(sequence) = bytes.strip_prefix("v:2|heartbeat:") {
        if let Ok(sequence) = sequence.parse() {
            return Ok(Msg::Heartbeat(sequence));
        }
    }
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(message) => format!("v:2|hello:{message}"),
        Msg::Heartbeat(sequence) => format!("v:2|heartbeat:{sequence}"),
    }
}

pub fn ping_roundtrip() -> Result<Msg, String> {
    decode(&encode(&Msg::Ping))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn decodes_ping_frame_successfully() {
        assert!(matches!(decode("ping"), Ok(Msg::Ping)));
    }

    #[test]
    fn heartbeat_roundtrips() {
        let message = Msg::Heartbeat(42);
        assert!(matches!(decode(&encode(&message)), Ok(Msg::Heartbeat(42))));
    }
}
